import{_ as e,o as a,c as s,a5 as i}from"./chunks/framework.DJo0M80U.js";const h=JSON.parse('{"title":"53. Conditional Compilation (#if, #ifdef, #ifndef)","description":"The Little Book of C — 53. Conditional Compilation (#if,","frontmatter":{"title":"53. Conditional Compilation (#if, #ifdef, #ifndef)","date":"2026-07-04","categories":["C 教程"],"tags":["C","Little Book of C","Compilation and Build"],"description":"The Little Book of C — 53. Conditional Compilation (#if,","source":"https://little-book-of.github.io/c/books/en-US/book.html","license":"CC BY-NC-SA 4.0","originalAuthor":"Duc-Tam Nguyen","section":53,"sidebarWeight":53,"lang":"en-US","alternateEn":"/posts/c教程/en-US/06-Compilation and Build/053-Conditional Compilation (if, ifdef, ifndef)","alternateZh":"/posts/c教程/zh-CN/06-编译与构建/053-Conditional Compilation (if, ifdef, ifndef)"},"headers":[],"relativePath":"posts/c教程/en-US/06-Compilation and Build/053-Conditional Compilation (if, ifdef, ifndef).md","filePath":"posts/c教程/en-US/06-Compilation and Build/053-Conditional Compilation (if, ifdef, ifndef).md","lastUpdated":1790163617000}'),t={name:"posts/c教程/en-US/06-Compilation and Build/053-Conditional Compilation (if, ifdef, ifndef).md"};function p(o,n,l,d,c,r){return a(),s("div",null,[...n[0]||(n[0]=[i(`<p>[中文版本](/posts/c教程/zh-CN/06-编译与构建/053-Conditional Compilation (if, ifdef, ifndef))</p><p>Conditional compilation lets you control which code gets compiled, not at runtime, but at compile time. This is how C programs adapt to different operating systems, architectures, or build configurations without changing source files manually.</p><p>Think of it as logic for the compiler’s eyes only.</p><h4 id="step-1-why-conditional-compilation-exists" tabindex="-1">Step 1. Why Conditional Compilation Exists <a class="header-anchor" href="#step-1-why-conditional-compilation-exists" aria-label="Permalink to &quot;Step 1. Why Conditional Compilation Exists&quot;">​</a></h4><p>Large C programs often need to handle differences such as:</p><ul><li>Platform (Windows, Linux, macOS, embedded)</li><li>Compiler (gcc, clang, MSVC)</li><li>Debug vs release builds</li><li>Optional features or experimental modules</li></ul><p>Instead of maintaining multiple versions of the same file, you can use conditional directives to selectively include or exclude code.</p><h4 id="step-2-the-core-directives" tabindex="-1">Step 2. The Core Directives <a class="header-anchor" href="#step-2-the-core-directives" aria-label="Permalink to &quot;Step 2. The Core Directives&quot;">​</a></h4><table tabindex="0"><thead><tr><th>Directive</th><th>Purpose</th></tr></thead><tbody><tr><td><code>#if </code></td><td>Compile code if expression is true</td></tr><tr><td><code>#ifdef </code></td><td>Compile if macro is defined</td></tr><tr><td><code>#ifndef </code></td><td>Compile if macro is not defined</td></tr><tr><td><code>#else</code></td><td>Alternate block</td></tr><tr><td><code>#elif </code></td><td>Else-if for preprocessor</td></tr><tr><td><code>#endif</code></td><td>Marks the end of a conditional block</td></tr></tbody></table><p>These work only during preprocessing, before compilation starts.</p><h4 id="tiny-code-platform-specific-compilation" tabindex="-1">Tiny Code: Platform-Specific Compilation <a class="header-anchor" href="#tiny-code-platform-specific-compilation" aria-label="Permalink to &quot;Tiny Code: Platform-Specific Compilation&quot;">​</a></h4><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#include &lt;stdio.h&gt;</span></span>
<span class="line"><span>int main(void) {</span></span>
<span class="line"><span>#ifdef _WIN32</span></span>
<span class="line"><span>    printf(&quot;Running on Windows\\n&quot;);</span></span>
<span class="line"><span>#elif __linux__</span></span>
<span class="line"><span>    printf(&quot;Running on Linux\\n&quot;);</span></span>
<span class="line"><span>#elif __APPLE__</span></span>
<span class="line"><span>    printf(&quot;Running on macOS\\n&quot;);</span></span>
<span class="line"><span>#else</span></span>
<span class="line"><span>    printf(&quot;Unknown platform\\n&quot;);</span></span>
<span class="line"><span>#endif</span></span>
<span class="line"><span>    return 0;</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>Compile and run on your system. The output will depend on which predefined macros your compiler sets automatically.</p><h4 id="step-3-enabling-and-disabling-features" tabindex="-1">Step 3. Enabling and Disabling Features <a class="header-anchor" href="#step-3-enabling-and-disabling-features" aria-label="Permalink to &quot;Step 3. Enabling and Disabling Features&quot;">​</a></h4><p>You can define flags at compile time with<code>-D</code>:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>gcc -DDEBUG log.c -o log</span></span></code></pre></div><p>In your code:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#ifdef DEBUG</span></span>
<span class="line"><span>    printf(&quot;Debug mode: extra checks enabled\\n&quot;);</span></span>
<span class="line"><span>#endif</span></span></code></pre></div><p>No recompilation needed to switch, just re-run<code>gcc</code> with or without<code>-DDEBUG</code>.</p><p>You can also assign values:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>gcc -DVERSION=2 main.c -o main</span></span></code></pre></div><p>Then:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#if VERSION &gt;= 2</span></span>
<span class="line"><span>    printf(&quot;New feature enabled!\\n&quot;);</span></span>
<span class="line"><span>#endif</span></span></code></pre></div><h4 id="step-4-guarding-code-with-ifndef" tabindex="-1">Step 4. Guarding Code with #ifndef <a class="header-anchor" href="#step-4-guarding-code-with-ifndef" aria-label="Permalink to &quot;Step 4. Guarding Code with #ifndef&quot;">​</a></h4><p>This is one of the most common idioms in C headers:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#ifndef CONFIG_H</span></span>
<span class="line"><span>#define CONFIG_H</span></span>
<span class="line"><span>#define MAX_CLIENTS 100</span></span>
<span class="line"><span>#define TIMEOUT_MS 3000</span></span>
<span class="line"><span>#endif</span></span></code></pre></div><p>It ensures that if<code>config.h</code> is included multiple times, it only gets processed once. Every header in the C standard library uses this pattern.</p><h4 id="step-5-excluding-experimental-code" tabindex="-1">Step 5. Excluding Experimental Code <a class="header-anchor" href="#step-5-excluding-experimental-code" aria-label="Permalink to &quot;Step 5. Excluding Experimental Code&quot;">​</a></h4><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#define ENABLE_EXPERIMENTAL 0</span></span>
<span class="line"><span>#if ENABLE_EXPERIMENTAL</span></span>
<span class="line"><span>void experimental_feature() {</span></span>
<span class="line"><span>    printf(&quot;Running experimental feature\\n&quot;);</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span>#endif</span></span></code></pre></div><p>If<code>ENABLE_EXPERIMENTAL</code> is set to<code>0</code>, this code is completely removed before compilation, it doesn’t even exist in the object file.</p><h4 id="tiny-code-debug-mode-example" tabindex="-1">Tiny Code: Debug Mode Example <a class="header-anchor" href="#tiny-code-debug-mode-example" aria-label="Permalink to &quot;Tiny Code: Debug Mode Example&quot;">​</a></h4><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#include &lt;stdio.h&gt;</span></span>
<span class="line"><span>#define DEBUG_MODE 1</span></span>
<span class="line"><span>void compute(int x) {</span></span>
<span class="line"><span>#if DEBUG_MODE</span></span>
<span class="line"><span>    printf(&quot;[DEBUG] compute() called with x=%d\\n&quot;, x);</span></span>
<span class="line"><span>#endif</span></span>
<span class="line"><span>    printf(&quot;Result: %d\\n&quot;, x * x);</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span>int main(void) {</span></span>
<span class="line"><span>    compute(5);</span></span>
<span class="line"><span>    return 0;</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>Output when<code>DEBUG_MODE</code> is 1:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[DEBUG] compute() called with x=5</span></span>
<span class="line"><span>Result: 25</span></span></code></pre></div><p>Set<code>DEBUG_MODE</code> to 0, recompile, and the<code>[DEBUG]</code> message disappears entirely.</p><h4 id="step-6-using-elif-and-else" tabindex="-1">Step 6. Using #elif and #else <a class="header-anchor" href="#step-6-using-elif-and-else" aria-label="Permalink to &quot;Step 6. Using #elif and #else&quot;">​</a></h4><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#define OS 2</span></span>
<span class="line"><span>#if OS == 1</span></span>
<span class="line"><span>    #define OS_NAME &quot;Windows&quot;</span></span>
<span class="line"><span>#elif OS == 2</span></span>
<span class="line"><span>    #define OS_NAME &quot;Linux&quot;</span></span>
<span class="line"><span>#else</span></span>
<span class="line"><span>    #define OS_NAME &quot;Unknown&quot;</span></span>
<span class="line"><span>#endif</span></span>
<span class="line"><span>int main(void) {</span></span>
<span class="line"><span>    printf(&quot;OS: %s\\n&quot;, OS_NAME);</span></span>
<span class="line"><span>    return 0;</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>Output:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>OS: Linux</span></span></code></pre></div><h4 id="step-7-combining-with-logical-operators" tabindex="-1">Step 7. Combining with Logical Operators <a class="header-anchor" href="#step-7-combining-with-logical-operators" aria-label="Permalink to &quot;Step 7. Combining with Logical Operators&quot;">​</a></h4><p>You can use<code>&amp;&amp;</code>,<code>||</code>, and<code>!</code> in preprocessor conditions.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#if defined(DEBUG) &amp;&amp; !defined(RELEASE)</span></span>
<span class="line"><span>    printf(&quot;Debug build only\\n&quot;);</span></span>
<span class="line"><span>#endif</span></span></code></pre></div><p>You can even use numeric comparisons:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#if VERSION &gt;= 3</span></span>
<span class="line"><span>    printf(&quot;Version 3+ detected\\n&quot;);</span></span>
<span class="line"><span>#endif</span></span></code></pre></div><h4 id="step-8-forcing-compilation-errors" tabindex="-1">Step 8. Forcing Compilation Errors <a class="header-anchor" href="#step-8-forcing-compilation-errors" aria-label="Permalink to &quot;Step 8. Forcing Compilation Errors&quot;">​</a></h4><p>Sometimes you want to stop compilation if a required macro is missing:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#ifndef API_KEY</span></span>
<span class="line"><span>#error &quot;API_KEY not defined! Please compile with -DAPI_KEY=your_key&quot;</span></span>
<span class="line"><span>#endif</span></span></code></pre></div><p>This is useful for configuration validation at build time.</p><h4 id="step-9-compiler-specific-macros" tabindex="-1">Step 9. Compiler-Specific Macros <a class="header-anchor" href="#step-9-compiler-specific-macros" aria-label="Permalink to &quot;Step 9. Compiler-Specific Macros&quot;">​</a></h4><p>Compilers automatically define macros to identify themselves and the environment.</p><table tabindex="0"><thead><tr><th>Macro</th><th>Meaning</th></tr></thead><tbody><tr><td><code>__GNUC__</code></td><td>Defined by GCC</td></tr><tr><td><code>__clang__</code></td><td>Defined by Clang</td></tr><tr><td><code>_MSC_VER</code></td><td>Defined by MSVC</td></tr><tr><td><code>__x86_64__</code></td><td>64-bit architecture</td></tr><tr><td><code>__arm__</code>,<code>__aarch64__</code></td><td>ARM architectures</td></tr><tr><td><code>__STDC__</code></td><td>Conforms to ANSI C standard</td></tr></tbody></table><p>You can use these to write portable, adaptive code:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#ifdef __clang__</span></span>
<span class="line"><span>    printf(&quot;Compiled with Clang\\n&quot;);</span></span>
<span class="line"><span>#elif defined(__GNUC__)</span></span>
<span class="line"><span>    printf(&quot;Compiled with GCC\\n&quot;);</span></span>
<span class="line"><span>#endif</span></span></code></pre></div><h4 id="tiny-code-portable-sleep-function" tabindex="-1">Tiny Code: Portable Sleep Function <a class="header-anchor" href="#tiny-code-portable-sleep-function" aria-label="Permalink to &quot;Tiny Code: Portable Sleep Function&quot;">​</a></h4><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#include &lt;stdio.h&gt;</span></span>
<span class="line"><span>#ifdef _WIN32</span></span>
<span class="line"><span>    #include &lt;windows.h&gt;</span></span>
<span class="line"><span>    #define SLEEP(ms) Sleep(ms)</span></span>
<span class="line"><span>#else</span></span>
<span class="line"><span>    #include &lt;unistd.h&gt;</span></span>
<span class="line"><span>    #define SLEEP(ms) usleep((ms) * 1000)</span></span>
<span class="line"><span>#endif</span></span>
<span class="line"><span>int main(void) {</span></span>
<span class="line"><span>    printf(&quot;Waiting...\\n&quot;);</span></span>
<span class="line"><span>    SLEEP(1000);</span></span>
<span class="line"><span>    printf(&quot;Done!\\n&quot;);</span></span>
<span class="line"><span>    return 0;</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>This compiles cleanly on both Windows and Linux with no code changes.</p><h4 id="why-it-matters" tabindex="-1">Why It Matters <a class="header-anchor" href="#why-it-matters" aria-label="Permalink to &quot;Why It Matters&quot;">​</a></h4><p>Conditional compilation makes your C code:</p><ul><li>Portable, same code runs on multiple systems</li><li>Configurable, features can be toggled at build time</li><li>Maintainable, no need for multiple codebases</li><li>Efficient, excluded code doesn’t even enter the binary</li></ul><p>In system software and embedded development, this is indispensable.</p><h4 id="try-it-yourself" tabindex="-1">Try It Yourself <a class="header-anchor" href="#try-it-yourself" aria-label="Permalink to &quot;Try It Yourself&quot;">​</a></h4><ol><li>Write a program that prints a different greeting depending on the OS.</li><li>Use<code>#if</code> and<code>#error</code> to enforce that only one of<code>DEBUG</code> or<code>RELEASE</code> can be defined.</li><li>Write a header that defines constants for different CPU architectures.</li><li>Add a feature flag (<code>ENABLE_LOGGING</code>) that can be turned on/off via<code>gcc -D</code>.</li><li>Use<code>#ifdef</code> and<code>#ifndef</code> to create a lightweight build-time configuration system.</li></ol><p>In the next section, you’ll take the next step toward clean, maintainable C code by learning about inline functions and header hygiene, modern, safer replacements for many macro patterns.</p>`,63)])])}const f=e(t,[["render",p]]);export{h as __pageData,f as default};
